export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + body pad 0.75 + body row 10.9 = 13.9 ≤ 13.9
  //   bars column inside body: 3 × StatBar 1.75 + 2 gaps 0.6 = 6.45 ≤ 10.9
  //   portrait 10.9 ≥ 4.5 floor; StatusEffectList 3.25 ≥ 2.75; SystemClock 2.5 ≥ 1.75
  // BUDGET width: pad 1.5 + portrait 7 + gap .75 + bars 40 + gap .75 + readouts (3×9 + 2×.5) = 28 + gap .75 + effects 26 + gap .75 + clock 11 = 116.3 ≤ 156.1

  const [health, setHealth] = useState(412);
  const maxHealth = 520;
  const [stamina, setStamina] = useState(78);
  const [cred, setCred] = useState(6400);
  const maxCred = 9000;
  const [armor] = useState(318);
  const [level] = useState(34);
  const [eddies] = useState(84210);
  const [now, setNow] = useState(Date.now());
  const [glitch, setGlitch] = useState(false);

  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const t = setInterval(() => {
      setStamina((s) => Math.max(18, Math.min(100, s + (Math.random() * 24 - 9))));
      setHealth((h) => Math.max(120, Math.min(maxHealth, h + (Math.random() * 30 - 12))));
      setCred((c) => Math.min(maxCred, c + Math.random() * 40));
    }, 1600);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const t = setInterval(() => {
      setGlitch(true);
      setTimeout(() => setGlitch(false), 180);
    }, 5200);
    return () => clearInterval(t);
  }, []);

  const effects = useMemo(
    () => [
      { id: "fx1", label: "Overclock", icon: "⚡", stacks: 2, remaining: 44, tone: "buff" as const },
      { id: "fx2", label: "Bleeding", icon: "🩸", remaining: 12, tone: "debuff" as const },
      { id: "fx3", label: "Berserk", icon: "☠", stacks: 1, remaining: 26, tone: "buff" as const },
      { id: "fx4", label: "Burn", icon: "🔥", remaining: 8, tone: "debuff" as const },
      { id: "fx5", label: "Second Heart", icon: "❤", stacks: 1, tone: "buff" as const },
    ],
    []
  );

  const hpTone = health / maxHealth < 0.3 ? "danger" : health / maxHealth < 0.6 ? "warning" : "accent";

  const Row = (props: { label: string; children: React.ReactNode; accent: string }) => (
    <div className="flex items-center gap-2">
      <span
        className={
          "w-24 text-[0.6rem] font-semibold uppercase tracking-[0.2em] leading-none " + props.accent
        }
      >
        {props.label}
      </span>
      <div className="flex-1 h-[1.75rem]">{props.children}</div>
    </div>
  );

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-zinc-950 bg-gradient-to-br from-zinc-950 via-black to-zinc-950 text-cyan-50 font-mono relative">
      {/* scanline sheen */}
      <div
        className="pointer-events-none absolute inset-0 opacity-25"
        style={{
          backgroundImage:
            "repeating-linear-gradient(180deg, rgba(34,211,238,0.14) 0px, rgba(34,211,238,0.14) 1px, transparent 1px, transparent 4px)",
        }}
      />
      <div
        className={
          "pointer-events-none absolute inset-0 transition-opacity duration-150 " +
          (glitch ? "opacity-100" : "opacity-0")
        }
        style={{
          background:
            "linear-gradient(90deg, rgba(232,121,249,0.14), transparent 30%, rgba(34,211,238,0.14) 60%, transparent)",
        }}
      />

      <div className="flex-none h-9 px-3 flex items-center justify-between border-b border-cyan-400/25 bg-gradient-to-r from-cyan-500/15 to-transparent relative">
        <div className="flex items-center gap-2 min-w-0">
          <span className="text-fuchsia-400 animate-pulse">◈</span>
          <span
            className={
              "text-xs font-bold uppercase tracking-[0.25em] text-yellow-300 drop-shadow-[0_0_6px_rgba(253,224,71,0.4)] truncate " +
              (glitch ? "translate-x-[2px] skew-x-6" : "")
            }
          >
            V // VITALS STATUS LINK
          </span>
        </div>
        <span className="text-[0.6rem] uppercase tracking-[0.2em] text-cyan-300/70 truncate">
          BIOMON · SANDEVISTAN SYNC NOMINAL
        </span>
      </div>

      <div className="flex-1 p-3 flex items-stretch gap-3 relative min-h-0 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {/* Portrait */}
        <div className="w-[7rem] h-full relative">
          <CharacterPortrait src="https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=400" alt="V" />
          <div className="pointer-events-none absolute -inset-px border border-fuchsia-400/40 rounded-lg shadow-[0_0_18px_-4px_rgba(232,121,249,0.6)]" />
        </div>

        {/* Bars */}
        <div className="flex-1 h-full flex flex-col justify-center gap-2 px-3 bg-black/60 border border-cyan-400/15 rounded-md shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]">
          <Row label="Health" accent="text-rose-400">
            <StatBar value={Math.round(health)} max={maxHealth} tone={hpTone as any} showNumeric />
          </Row>
          <Row label="Stamina" accent="text-cyan-300/80">
            <StatBar value={Math.round(stamina)} max={100} segments={10} tone="neutral" />
          </Row>
          <Row label="St. Cred" accent="text-orange-400">
            <StatBar value={Math.round(cred)} max={maxCred} tone="accent" showNumeric />
          </Row>
        </div>

        {/* Readouts */}
        <div className="w-[28rem] h-full grid grid-cols-3 gap-2">
          {[
            { k: "ARMOR", node: <StatReadout value={armor} unit="AP" delta={12} tone="accent" /> },
            { k: "LEVEL", node: <StatReadout value={level} unit="LV" tone="neutral" /> },
            { k: "EDDIES", node: <StatReadout value={eddies.toLocaleString()} unit="€$" delta={340} tone="neutral" /> },
          ].map((r) => (
            <div
              key={r.k}
              className="h-full flex flex-col justify-center gap-1 px-2 bg-zinc-900/80 backdrop-blur-sm border border-cyan-400/25 rounded-lg shadow-[0_0_20px_-4px_rgba(34,211,238,0.35)] transition-all duration-200 hover:border-yellow-300/70"
            >
              <span className="text-[0.6rem] uppercase tracking-[0.2em] text-cyan-300/70 leading-none">{r.k}</span>
              <div className="h-[3.25rem]">{r.node}</div>
            </div>
          ))}
        </div>

        {/* Status effects */}
        <div className="w-[26rem] h-full flex flex-col justify-center gap-1 px-2 bg-black/60 border border-cyan-400/15 rounded-md shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]">
          <span className="text-[0.6rem] uppercase tracking-[0.2em] text-fuchsia-400 leading-none">
            ACTIVE EFFECTS
          </span>
          <div className="h-[3.5rem]">
            <StatusEffectList effects={effects} />
          </div>
        </div>

        {/* Clock */}
        <div className="w-[11rem] h-full flex flex-col justify-center gap-1 px-2 bg-zinc-900/80 border border-cyan-400/25 rounded-lg shadow-[0_0_20px_-4px_rgba(34,211,238,0.35)]">
          <span className="text-[0.6rem] uppercase tracking-[0.2em] text-cyan-300/70 leading-none">
            NC LOCAL
          </span>
          <div className="h-[2.75rem]">
            <SystemClock time={now} format="24h" />
          </div>
        </div>
      </div>
    </div>
  );
}

export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + points 2.75 + gap 0.5 + 5×attrRow(2.75)=13.75 + gaps 4×0.375=1.5 + gap 0.5 + perkhdr 1 + PerkList 8.5 + padding 1.5 + footer 1.75 = 33.5 ≤ 38.1
  // BUDGET width: padding 1.5 + label 8 + StatReadout 3.5 + gap 0.5 + Stepper 7 + bar flex = 20.5 ≤ 38.1

  const [attrs, setAttrs] = useState<{ id: string; label: string; abbr: string; value: number }[]>([
    { id: "body", label: "Body", abbr: "BOD", value: 12 },
    { id: "reflexes", label: "Reflexes", abbr: "REF", value: 9 },
    { id: "technical", label: "Technical Ability", abbr: "TEC", value: 14 },
    { id: "intelligence", label: "Intelligence", abbr: "INT", value: 7 },
    { id: "cool", label: "Cool", abbr: "COO", value: 10 },
  ]);
  const [base] = useState<Record<string, number>>({ body: 12, reflexes: 9, technical: 14, intelligence: 7, cool: 10 });
  const [pool, setPool] = useState(7);
  const [sel, setSel] = useState("body");
  const [flash, setFlash] = useState<string | null>(null);

  const perkMap: Record<string, { id: string; label: string; description?: string; rank?: number; maxRank?: number; unlocked?: boolean }[]> = {
    body: [
      { id: "b1", label: "Painkiller", description: "Health regen extends into combat.", rank: 2, maxRank: 3, unlocked: true },
      { id: "b2", label: "Wolverine", description: "+30% health regen rate.", rank: 1, maxRank: 2, unlocked: true },
      { id: "b3", label: "Dorph-Head", description: "Gain adrenaline on finisher.", rank: 0, maxRank: 3, unlocked: false },
      { id: "b4", label: "Quake", description: "Ground slam shockwave.", rank: 0, maxRank: 1, unlocked: false },
    ],
    reflexes: [
      { id: "r1", label: "Slippery", description: "+25% evasion while dodging.", rank: 3, maxRank: 3, unlocked: true },
      { id: "r2", label: "Air Dash", description: "Dash mid-air once.", rank: 1, maxRank: 1, unlocked: true },
      { id: "r3", label: "Mongoose", description: "Perfect dodge slows time.", rank: 0, maxRank: 2, unlocked: false },
    ],
    technical: [
      { id: "t1", label: "Glutton For War", description: "Regen RAM on grenade hit.", rank: 2, maxRank: 2, unlocked: true },
      { id: "t2", label: "Renaissance Punk", description: "+1 to all attributes ≥ 9.", rank: 1, maxRank: 1, unlocked: true },
      { id: "t3", label: "Edgerunner", description: "Exceed cyberware capacity.", rank: 1, maxRank: 2, unlocked: true },
      { id: "t4", label: "Chrome Compressor", description: "+10 cyberware capacity.", rank: 0, maxRank: 3, unlocked: false },
    ],
    intelligence: [
      { id: "i1", label: "Embedded Breach", description: "Auto-breach on quickhack.", rank: 1, maxRank: 2, unlocked: true },
      { id: "i2", label: "Overclock", description: "Spend health as RAM.", rank: 0, maxRank: 1, unlocked: false },
      { id: "i3", label: "Bloodware", description: "Quickhacks deal damage.", rank: 0, maxRank: 3, unlocked: false },
    ],
    cool: [
      { id: "c1", label: "Ninjutsu", description: "+35% stealth damage.", rank: 2, maxRank: 3, unlocked: true },
      { id: "c2", label: "Deep Breath", description: "Extended focus window.", rank: 1, maxRank: 2, unlocked: true },
      { id: "c3", label: "Killer Instinct", description: "+30% crouch move speed.", rank: 0, maxRank: 2, unlocked: false },
    ],
  };

  const setAttr = (id: string, v: number) => {
    setAttrs((prev) => {
      const cur = prev.find((a) => a.id === id);
      if (!cur) return prev;
      const min = base[id];
      const next = Math.max(min, Math.min(20, v));
      const delta = next - cur.value;
      if (delta > 0 && delta > pool) return prev;
      setPool((p) => p - delta);
      return prev.map((a) => (a.id === id ? { ...a, value: next } : a));
    });
    setSel(id);
    setFlash(id);
    setTimeout(() => setFlash(null), 450);
  };

  const spent = attrs.reduce((s, a) => s + (a.value - base[a.id]), 0);
  const selAttr = attrs.find((a) => a.id === sel)!;

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-zinc-950 bg-gradient-to-br from-zinc-950 via-black to-zinc-950 text-cyan-50 font-mono">
      <div className="h-9 flex-none flex items-center justify-between px-3 border-b border-cyan-400/25 bg-gradient-to-r from-cyan-500/15 to-transparent">
        <div className="flex items-center gap-2">
          <span className="text-fuchsia-400 animate-pulse">◈</span>
          <span className="text-xs font-bold uppercase tracking-[0.25em] text-yellow-300 drop-shadow-[0_0_6px_rgba(253,224,71,0.4)]">
            Attributes
          </span>
        </div>
        <span className="text-[0.6rem] uppercase tracking-[0.2em] text-cyan-300/70">V // BUILD.SYS</span>
      </div>

      <div className="flex-1 flex flex-col gap-2 p-3 min-h-0 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {/* Available points */}
        <div className="flex-none flex items-center gap-3 rounded-md border border-cyan-400/15 bg-black/60 px-2 py-2 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]">
          <div className="flex flex-col leading-none">
            <span className="text-[0.65rem] font-medium uppercase tracking-widest text-cyan-300/70">Attribute Points</span>
            <span className="text-[0.6rem] uppercase tracking-[0.15em] text-zinc-500">Spent {spent}</span>
          </div>
          <div className="ml-auto" style={{ width: "5rem", height: "2rem" }}>
            <StatReadout value={pool} unit="PTS" tone={pool > 0 ? "accent" : "neutral"} />
          </div>
        </div>

        {/* Attribute rows */}
        <div className="flex-none flex flex-col gap-1.5">
          {attrs.map((a) => {
            const active = sel === a.id;
            return (
              <div
                key={a.id}
                onClick={() => setSel(a.id)}
                className={
                  "flex items-center gap-2 rounded-md border px-2 py-1 transition-all duration-200 cursor-pointer " +
                  (active
                    ? "border-yellow-300/70 bg-cyan-400/10 shadow-[0_0_12px_-2px_rgba(253,224,71,0.5)]"
                    : "border-cyan-400/20 bg-black/40 hover:border-yellow-300/70 hover:bg-cyan-400/10")
                }
              >
                <div className="flex flex-col leading-none" style={{ width: "7.5rem" }}>
                  <span className="truncate text-xs font-semibold uppercase tracking-[0.18em] text-cyan-50">{a.label}</span>
                  <span className="text-[0.6rem] uppercase tracking-[0.2em] text-zinc-500">{a.abbr} — LV {a.value}</span>
                </div>

                <div style={{ width: "3.75rem", height: "2rem" }}>
                  <StatReadout
                    value={a.value}
                    delta={a.value - base[a.id] !== 0 ? a.value - base[a.id] : undefined}
                    tone={flash === a.id ? "accent" : a.value >= 15 ? "warning" : "neutral"}
                  />
                </div>

                <div className="flex-1 flex h-4 items-center gap-[2px] px-1">
                  {Array.from({ length: 20 }).map((_, i) => (
                    <div
                      key={i}
                      className={
                        "h-full flex-1 rounded-[1px] transition-all duration-500 " +
                        (i < a.value
                          ? i < base[a.id]
                            ? "bg-cyan-400/80 shadow-[0_0_10px_rgba(34,211,238,0.7)]"
                            : "bg-yellow-300 shadow-[0_0_10px_rgba(253,224,71,0.8)]"
                          : "bg-cyan-400/10")
                      }
                    />
                  ))}
                </div>

                <div style={{ width: "7rem", height: "2rem" }}>
                  <Stepper
                    value={a.value}
                    min={base[a.id]}
                    max={20}
                    step={1}
                    onChange={(v) => setAttr(a.id, v)}
                    disabled={pool <= 0 && a.value <= base[a.id]}
                  />
                </div>
              </div>
            );
          })}
        </div>

        {/* Perk highlights */}
        <div className="flex-1 flex flex-col gap-1">
          <div className="flex-none flex items-baseline justify-between">
            <span className="text-xs font-semibold uppercase tracking-[0.2em] text-cyan-300/80">
              Perk Highlights
            </span>
            <span className="rounded-full border border-fuchsia-400/40 px-2 py-0.5 text-[0.6rem] uppercase tracking-[0.15em] text-fuchsia-400">
              {selAttr.label}
            </span>
          </div>
          <div className="flex-1 rounded-md border border-cyan-400/15 bg-black/60 p-1 shadow-[inset_0_0_12px_rgba(0,0,0,0.8)]" style={{ minHeight: "8.5rem" }}>
            <PerkList perks={perkMap[sel]} />
          </div>
        </div>
      </div>

      <div className="h-7 flex-none flex items-center justify-between px-3 border-t border-cyan-400/20 bg-black/50 text-[0.6rem] font-medium uppercase tracking-[0.2em] text-cyan-300/70">
        <span>{pool > 0 ? "◆ Points Pending Allocation" : "◆ Allocation Locked"}</span>
        <span className="text-lime-300">SYNC // VITALS · CHROME</span>
      </div>
    </div>
  );
}

export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + capacity 3.25 + gap 0.5 + diagram 25.5 + gap 0.5 + footer 1.75 = 33.75 ≤ 38.1
  // BUDGET width: pad 0.5 + diagram 15.5 + gap 0.5 + detail 23.5 + pad 0.5 = 40.5 ≤ 41.6

  type Imp = { id: string; label: string; icon?: string; rarity?: 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary'; stats?: { label: string; value: string | number }[]; cost: number };

  const POOL: Record<string, Imp[]> = {
    cortex: [
      { id: 'c1', label: 'Kerenzikov', icon: '⌁', rarity: 'epic', stats: [{ label: 'SLOW-MO', value: '+1.5s' }, { label: 'CRIT', value: '+9%' }], cost: 14 },
      { id: 'c2', label: 'Axolotl', icon: '⌁', rarity: 'legendary', stats: [{ label: 'CD RED', value: '+18%' }, { label: 'RAM', value: '+3' }], cost: 20 },
    ],
    ocular: [
      { id: 'o1', label: 'Kiroshi Mk.3', icon: '◉', rarity: 'rare', stats: [{ label: 'SCAN', value: '+40%' }, { label: 'HEADSHOT', value: '+12%' }], cost: 8 },
      { id: 'o2', label: 'Ocular Grid', icon: '◉', rarity: 'epic', stats: [{ label: 'ACCURACY', value: '+15%' }, { label: 'SCAN', value: '+22%' }], cost: 11 },
    ],
    nervous: [
      { id: 'n1', label: 'Reflex Tuner', icon: '⚡', rarity: 'epic', stats: [{ label: 'REFLEX', value: '+11%' }, { label: 'MITIG', value: '+8%' }], cost: 13 },
      { id: 'n2', label: 'Synaptic Acc.', icon: '⚡', rarity: 'legendary', stats: [{ label: 'SLOW-MO', value: '+2.2s' }, { label: 'STAM', value: '+14%' }], cost: 17 },
    ],
    circ: [
      { id: 'b1', label: 'Blood Pump', icon: '❤', rarity: 'rare', stats: [{ label: 'HEALTH', value: '+120' }, { label: 'REGEN', value: '+6/s' }], cost: 10 },
      { id: 'b2', label: 'Biomonitor', icon: '❤', rarity: 'uncommon', stats: [{ label: 'HEAL', value: 'AUTO' }, { label: 'REGEN', value: '+3/s' }], cost: 6 },
    ],
    skeleton: [
      { id: 's1', label: 'Titanium Bones', icon: '⛨', rarity: 'rare', stats: [{ label: 'CARRY', value: '+60' }, { label: 'ARMOR', value: '+48' }], cost: 9 },
      { id: 's2', label: 'Dense Marrow', icon: '⛨', rarity: 'epic', stats: [{ label: 'ARMOR', value: '+74' }, { label: 'STAGGER', value: '-20%' }], cost: 12 },
    ],
    arms: [
      { id: 'a1', label: 'Mantis Blades', icon: '⚔', rarity: 'legendary', stats: [{ label: 'DMG', value: '+214' }, { label: 'BLEED', value: '+30%' }], cost: 16 },
      { id: 'a2', label: 'Gorilla Arms', icon: '⚔', rarity: 'epic', stats: [{ label: 'DMG', value: '+180' }, { label: 'BODY', value: '+2' }], cost: 12 },
    ],
    legs: [
      { id: 'l1', label: 'Reinf. Tendons', icon: '⤒', rarity: 'rare', stats: [{ label: 'JUMP', value: '+DBL' }, { label: 'STAM', value: '+10%' }], cost: 7 },
      { id: 'l2', label: 'Fortified Ankles', icon: '⤒', rarity: 'epic', stats: [{ label: 'CHARGE', value: '+35%' }, { label: 'FALL', value: '-50%' }], cost: 9 },
    ],
    skin: [
      { id: 'k1', label: 'Subdermal Armor', icon: '▤', rarity: 'epic', stats: [{ label: 'ARMOR', value: '+96' }, { label: 'RESIST', value: '+18%' }], cost: 11 },
      { id: 'k2', label: 'Optical Camo', icon: '▤', rarity: 'legendary', stats: [{ label: 'STEALTH', value: '+45%' }, { label: 'EVASION', value: '+12%' }], cost: 15 },
    ],
  };

  const REGIONS = [
    { id: 'cortex', name: 'Frontal Cortex', x: 0.5, y: 0.06 },
    { id: 'ocular', name: 'Ocular System', x: 0.17, y: 0.2 },
    { id: 'nervous', name: 'Nervous System', x: 0.83, y: 0.2 },
    { id: 'circ', name: 'Circulatory', x: 0.17, y: 0.42 },
    { id: 'skin', name: 'Integumentary', x: 0.83, y: 0.42 },
    { id: 'skeleton', name: 'Skeleton', x: 0.5, y: 0.6 },
    { id: 'arms', name: 'Arms', x: 0.17, y: 0.79 },
    { id: 'legs', name: 'Legs', x: 0.83, y: 0.79 },
  ];

  const [equipped, setEquipped] = useState<Record<string, number>>({
    cortex: 0, ocular: 0, nervous: -1, circ: 0, skin: -1, skeleton: 0, arms: 0, legs: -1,
  });
  const [sel, setSel] = useState('cortex');
  const [pulse, setPulse] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setPulse((p) => (p + 1) % 100), 90);
    return () => clearInterval(t);
  }, []);

  const CAP = 96;
  const used = useMemo(
    () => Object.keys(equipped).reduce((s, k) => s + (equipped[k] >= 0 ? POOL[k][equipped[k]].cost : 0), 0),
    [equipped]
  );

  const current = equipped[sel] >= 0 ? POOL[sel][equipped[sel]] : null;
  const region = REGIONS.find((r) => r.id === sel)!;

  const swap = () => {
    setEquipped((e) => {
      const next = (e[sel] + 1) % POOL[sel].length;
      const cand = POOL[sel][next];
      const base = used - (e[sel] >= 0 ? POOL[sel][e[sel]].cost : 0);
      if (base + cand.cost > CAP) return e;
      return { ...e, [sel]: next };
    });
  };
  const unequip = () => setEquipped((e) => ({ ...e, [sel]: -1 }));

  const tone: 'accent' | 'warning' | 'danger' = used / CAP > 0.92 ? 'danger' : used / CAP > 0.75 ? 'warning' : 'accent';

  const aggregate = useMemo(() => {
    let armor = 0, health = 0;
    Object.keys(equipped).forEach((k) => {
      if (equipped[k] < 0) return;
      POOL[k][equipped[k]].stats?.forEach((s) => {
        const n = parseInt(String(s.value).replace(/[^0-9-]/g, '')) || 0;
        if (s.label === 'ARMOR') armor += n;
        if (s.label === 'HEALTH') health += n;
      });
    });
    return { armor, health };
  }, [equipped]);

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-zinc-950 bg-gradient-to-br from-zinc-950 via-black to-zinc-950 text-cyan-50 font-mono">
